INSERT INTO `oc_hb_build_template` (`template_label`, `store_id`, `loaded_template_id`, `email_type_id`, `editor`, `draft_head`, `draft_body`, `options`, `email_options`, `cross_selling_options`, `date_added`, `date_modified`) VALUES('Out of Stock Alert - Sample', 0, 9999, 6, 'ckeditor', '', '<meta content=\"text/html; charset=utf-8\" http-equiv=\"Content-Type\" />\n<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\" />\n<title></title>\n<div style=\"overflow: hidden;\">\n<div style=\"background:#fff;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px;color:#222;line-height:18px\">\n<div style=\"background:#F7F9FB;padding:0 2% 2%\">\n<div>&nbsp;</div>\n\n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-repeat:repeat;background-position:center;\" width=\"100%\">\n	<tbody>\n		<tr style=\"height:10px;\">\n			<td style=\"padding: 10px;\">&nbsp;</td>\n		</tr>\n		<tr>\n			<td align=\"center\">\n			<div style=\"max-width:600px\">\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"text-align:left;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px; color:#222;line-height:18px;width:100%\">\n				<tbody>\n					<tr>\n						<td>\n						<div style=\"background:#FFFFFF;padding:3.5%;border:1px solid #880505\">\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n							<tbody>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\"><a href=\"{product_link}\">{name}</a> is out of stock.</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">\n									<table cellpadding=\"10\">\n										<tbody>\n											<tr>\n												<td>{product_image}</td>\n												<td><b>{name}</b><br />\n												Model: {model}<br />\n												SKU: {sku}<br />\n												Price: {price}</td>\n											</tr>\n										</tbody>\n									</table>\n									</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom: 20px;\" valign=\"top\">\n									<p style=\"color:red;\">Total Available Quantity: {quantity}</p>\n									</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">{product_options}</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">Product Link: <a href=\"{product_link}\">{product_link}</a></td>\n								</tr>\n							</tbody>\n						</table>\n						</div>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			</td>\n		</tr>\n	</tbody>\n</table>\n</div>\n</div>\n\n<div style=\"background:#F7F9FB;padding:0 2% 2%\">\n<div>&nbsp;</div>\n</div>\n</div>\n', '', '{\"sender_name\":\"{config_name}\",\"sender_email\":\"{config_email}\",\"email_bcc\":\"\",\"email_replyto\":\"\",\"email_subject\":\"{name} is out-of-stock\",\"email_type_id\":\"2\"}', '', '2021-08-29 12:12:52', '2021-09-26 21:32:08');
INSERT INTO `oc_hb_build_template` (`template_label`, `store_id`, `loaded_template_id`, `email_type_id`, `editor`, `draft_head`, `draft_body`, `options`, `email_options`, `cross_selling_options`, `date_added`, `date_modified`) VALUES('Low Stock Alert - Sample', 0, 9999, 6, 'ckeditor', '', '<meta content=\"text/html; charset=utf-8\" http-equiv=\"Content-Type\" />\n<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\" />\n<title></title>\n<div style=\"overflow: hidden;\">\n<div style=\"background:#fff;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px;color:#222;line-height:18px\">\n<div style=\"background:#F7F9FB;padding:0 2% 2%\">\n<div>&nbsp;</div>\n\n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-repeat:repeat;background-position:center;\" width=\"100%\">\n	<tbody>\n		<tr style=\"height:10px;\">\n			<td style=\"padding: 10px;\">&nbsp;</td>\n		</tr>\n		<tr>\n			<td align=\"center\">\n			<div style=\"max-width:600px\">\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"text-align:left;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px; color:#222;line-height:18px;width:100%\">\n				<tbody>\n					<tr>\n						<td>\n						<div style=\"background:#FFFFFF;padding:3.5%;border:1px solid #ED5F00\">\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n							<tbody>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\"><a href=\"{product_link}\">{name}</a> is running low on stock.</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">\n									<table cellpadding=\"10\">\n										<tbody>\n											<tr>\n												<td>{product_image}</td>\n												<td><b>{name}</b><br />\n												Model: {model}<br />\n												SKU: {sku}<br />\n												Price: {price}</td>\n											</tr>\n										</tbody>\n									</table>\n									</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom: 20px;\" valign=\"top\">\n									<p style=\"color:red;\">Total Available Quantity: {quantity}</p>\n									</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">{product_options}</td>\n								</tr>\n								<tr>\n									<td align=\"left\" style=\"padding-bottom:20px\" valign=\"top\">Product Link: <a href=\"{product_link}\">{product_link}</a></td>\n								</tr>\n							</tbody>\n						</table>\n						</div>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			</td>\n		</tr>\n	</tbody>\n</table>\n</div>\n</div>\n\n<div style=\"background:#F7F9FB;padding:0 2% 2%\">\n<div>&nbsp;</div>\n</div>\n</div>\n', '', '{\"sender_name\":\"{config_name}\",\"sender_email\":\"{config_email}\",\"email_bcc\":\"\",\"email_replyto\":\"\",\"email_subject\":\"{name} is low on stock \",\"email_type_id\":\"2\"}', '', '2021-09-21 16:16:31', '2021-09-26 21:30:56');